//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 		HE_VFD_WEG_CFW500_Wrapper                                                                                                                                                                                                                                                                    
//	CREATOR:	    Jan Magne Dybvik, Helgevold Elektro                                                                                                                                                                                                                                            
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
// 1.0.0					07.03.2025		JMD							Initial Release
//	1.0.1					15.04.2025		Ruben Byman			Added LOTO and bugfix statistics
// 1.0.2					19.08.2025		FB 							Inp Remote changed from bit 2 Statusword 1 to bit 12 statusword 1 Remote
// 1.0.3					26.02.2026		WV 							Updated scaling of power input
//===============================================================================================================================
//
//		DESCRIPTION:
//		Interface between HE_FrekvOmf_Logic and WEG CFW500 VFD
//
//		FUNCTION:
//		Translates Ethernet/IP input and output asseblies forCFW500 to HE_FrekvOmf_Logic Parameters
//
//===============================================================================================================================

(*************************************************************************
 *	IMPORTANT!
 * Do NOT use WEG EDS file
 * Use Omron Generic EDS EIP
 * Input Assembly: 150
 * Input Size (Bytes): 28
 * Output Assembly: 100
 * Output Size (Bytes): 4
 *
 *************************************************************************

// Eth: Read Word #03: 690		WEG Status Word 2
// Eth: Read Word #04: 12		Digital Inputs
// Eth: Read Word #05: 3			Motor Current
// Eth: Read Word #06: 7			Output Voltage
// Eth: Read Word #07: 10		Output Power
// Eth: Read Word #08: 42		Time Powered
// Eth: Read Word #09: 44	 	Output Energy (kWh)
// Eth: Read Word #10: 6			InverterStatus
// Eth: Read Word #11: 49		Present Fault
// Eth: Read Word #12: 48		Present Alarm
// Eth: Read Word #13: 30		Module Temperature
// Eth: Read Word #14: 34		Internal Temperature

(*************************************************************************
 *	Update Inputs
 *************************************************************************)
 
 // Config Parameter
 Ext_VFD.EXT_Engineering.Auto_Visible:= 						Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=						Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=		FALSE;
 
// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerName;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
Wrk_Direction :=											TRUE;
FB_VFD_Logic.Inp_AutoRunFwd :=				Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef :=			Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Interlock := 					Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Cfg_STO_InUse:=					Cfg_STO_InUse;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;
FB_VFD_Logic.Cfg_LOTO_InUse :=				Cfg_LOTO_InUse;
FB_VFD_Logic.Inp_LOTO :=							Inp_LOTO;
FB_VFD_Logic.Inp_ComFault :=					HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_DriveIP);

// Fieldbus Input
FB_VFD_Logic.Inp_LocalStop := 					FALSE;
FB_VFD_Logic.Inp_Online :=						TRUE;
FB_VFD_Logic.Inp_STO :=	 						Ext_VFD_Input.StatusWord1.Bit[0];
FB_VFD_Logic.Inp_VoltageEnabled :=			Ext_VFD_Input.StatusWord1.Bit[9];
FB_VFD_Logic.Inp_Error  := 							Ext_VFD_Input.StatusWord1.Bit[15];
FB_VFD_Logic.Inp_Warning := 					Ext_VFD_Input.StatusWord1.Bit[7];
FB_VFD_Logic.Inp_Remote :=					 	Ext_VFD_Input.StatusWord1.Bit[12];
FB_VFD_Logic.Inp_RunningFwd := 				Ext_VFD_Input.StatusWord1.Bit[8] AND Ext_VFD_Input.StatusWord1.Bit[10];
FB_VFD_Logic.Inp_RunningRev :=				FALSE;
FB_VFD_Logic.Inp_Ready := 						Ext_VFD_Input.StatusWord1.Bit[9] AND NOT Ext_VFD_Input.StatusWord1.Bit[6];

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(SclIn:=INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.ActualSpeed.Wrd)),
												  	X0:=REAL#0.0,
												  	Y0:=REAL#0.0,
												  	X1:=REAL#8192.0,
												  	Y1:=REAL#100.0);

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
FB_VFD_Logic.Inp_Power :=  	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.Power.Wrd)) * 0.1; // kW
FB_VFD_Logic.Inp_Current :=	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.Current.Wrd)) * 0.1; //A
FB_VFD_Logic.Inp_Energy := 	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.kWh.Wrd)); //kWh
	
(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)

IF FB_VFD_Logic.Inp_RunningFwd THEN
		Wrk_Runtime := ADD_TIME(Wrk_Runtime, GetMyTaskInterval()); 
END_IF;
	
FB_VFD_Logic.Inp_VFD_TotalRunTime := 	LINT_TO_UDINT( TimeToSec(Wrk_Runtime) / 3600);
FB_VFD_Logic.Inp_VFD_TotalOnTime := 		WORD_TO_ULINT(Ext_VFD_Input.PowerOnTime.Wrd);

(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= 			HE_WEG_Drive_Fault(Inp_InverterFault := Ext_VFD_Input.PresentFault.Wrd);
FB_VFD_Logic.Inp_Active_Warning:= 		HE_WEG_Drive_Alarms(Inp_InverterFault:=Ext_VFD_Input.PresentAlarm.Wrd);
FB_VFD_Logic.Inp_Actual_State:= 			HE_WEG_Drive_State(Inp_InverterStatus := Ext_VFD_Input.InverterStatus.Wrd);
	
(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update Outputs
 *************************************************************************)

// Output Parameters
Sts_Alarm :=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto := 	FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd := 		FB_VFD_Logic.Inp_RunningFwd;
Val_ModuleTemp := 	WORD_TO_INT(Ext_VFD_Input.ModuleTemperature.Wrd);
Val_InternalTemp := 	WORD_TO_INT(Ext_VFD_Input.InternalTemperature .Wrd);

// Fieldbus Output
Ext_VFD_Output.ControlWord.Wrd := 16#0;
Ext_VFD_Output.ControlWord.Bit[0] := FB_VFD_Logic.Out_RunFwd; // Run FWD Command
Ext_VFD_Output.ControlWord.Bit[1] := FB_VFD_Logic.Out_Enable; // Enable VFD
Ext_VFD_Output.ControlWord.Bit[2] := Wrk_Direction;
Ext_VFD_Output.ControlWord.Bit[7] := FB_VFD_Logic.Out_FaultReset; // Fault Reset

Ext_VFD_Output.SpeedReference.Wrd:= INT_TO_WORD(REAL_TO_INT(ScaleTrans(
												SclIn:=FB_VFD_Logic.Out_SpeedRef,
												X0:=0.0,
												Y0:=0.0,
												X1:=100.0,
												Y1:=8192.0)));
